"""Admin-assigned dashboard sections, enforced before account API dispatch."""
FEATURES={'investment':'Investment','resources':'Server resources','sectors':'Sector rotation','handoff':'Analysis handoff','straddles':'Long Straddles','broker':'Live feed & positions','holdings':'Holdings review','screener':'Screener','settings':'Risk Guardrails','ema-band':'EMA Band','renko-supertrend':'Renko Supertrend','ema-cross':'RSI based SMA','kama':'KAMA Strategy','delta-india':'Delta India','trade-parser':'FYERS Trade Parser','telegram-parser':'Telegram Trade Parser','renko-engine':'Renko Engine','broker-connection':'Broker connection','runner-jobs':'Saved analysis and runner jobs','user-guide':'Help / User guide'}
COMMON={'/api/auth/status','/api/auth/start','/api/workspace-context','/api/paper-capital/status'}
PREFIXES=[('/api/investment/',{'investment'}),('/api/delta-india/holdings-analysis',{'holdings','broker'}),('/api/dhan/holdings-analysis',{'holdings','broker'}),('/api/motilal/holdings-analysis',{'holdings','broker'}),('/api/motilal/sector-analysis',{'sectors'}),('/api/motilal/analysis-handoff/',{'handoff'}),('/api/motilal/chartink/',{'screener'}),('/api/motilal/trade-ticket/',{'handoff','screener'}),('/api/motilal/',{'broker'}),('/api/resources',{'resources'}),('/api/holdings-analysis',{'holdings','broker'}),('/api/dhan/sector-analysis',{'sectors'}),('/api/renko-engine/',{'renko-engine'}),('/api/band-dhan/',{'ema-band'}),('/api/kama-dhan/',{'kama'}),('/api/ema-dhan/',{'ema-cross'}),('/api/dhan/',{'broker','handoff','screener'}),('/api/renko-',{'renko-supertrend'}),('/api/ema-crossover/',{'ema-cross'}),('/api/ema-band/',{'ema-band'}),('/api/kama/',{'kama'}),('/api/delta-india/',{'delta-india'}),('/api/analysis-handoff/',{'handoff'}),('/api/trade-ticket/',{'handoff'}),('/api/chartink/',{'screener'}),('/api/automation/',{'settings'}),('/api/trade-recommendation/',{'trade-parser','telegram-parser'}),('/api/telegram/',{'telegram-parser'}),('/api/whatsapp/',{'trade-parser'}),('/api/sector-analysis',{'sectors'}),('/api/heatmap',{'sectors'}),('/api/rsi-table',{'ema-cross','sectors'}),('/api/account',{'broker'}),('/api/live-pnl',{'broker'}),('/api/realized-pnl',{'broker'})]
def allowed(user,path):
 if user.get('admin') or not path.startswith('/api/'):return True
 if path in COMMON:return True
 assigned=set(user.get('features',[]))
 if path.startswith('/api/jobs'):return bool(assigned & {'investment','broker','runner-jobs','handoff','screener','holdings','trade-parser','telegram-parser','renko-supertrend','ema-band','ema-cross','kama','delta-india','straddles','renko-engine'})
 if path in {'/api/ema-band/underlying-search','/api/ema-band/master-search','/api/ema-band/master-status','/api/ema-band/atm-option'}:
  return bool(assigned & {'ema-band','renko-supertrend','kama','ema-cross','handoff','renko-engine'})
 if any(path.startswith(p) for p in ['/api/nifty-straddle','/api/sensex-straddle','/api/straddle-squareoff/']):return 'straddles' in assigned
 for prefix,features in PREFIXES:
  if path.startswith(prefix):return bool(assigned & features)
 return False
